CREATE OR REPLACE FUNCTION public.et_upload_unzip_extractation(parameter json, ref refcursor)
 RETURNS refcursor
 LANGUAGE plpgsql
AS $function$
declare nUserid uuid;nBundleid uuid;nSectionid uuid;jFolders jsonb;nCaseid uuid;nExistsid uuid;parentid uuid;
rec jsonb;nMainbundleid uuid;nUnicno text;nUid int; notice_message TEXT;
