drop table if exists temp_folders;
create temp table temp_folders as 
select * from jsonb_to_recordset(jFolders) as ("id" text,"name" text,"parentId" text,"nBundleid" uuid,"isFolder" boolean,"nParentbundleid" uuid,"nBundledetailid" uuid,"cSavepath" text,"path" text);

    FOR rec IN SELECT * FROM jsonb_array_elements(jFolders)
     LOOP
     
     if(rec->>'isFolder')then 
        nExistsid = null::uuid;
        parentid = nBundleid;
        
        if(coalesce(rec->>'parentId','0')!='0')then
            if exists (select * from "BundleMaster" where "nSectionid" = nSectionid and "cTempid" = rec->>'parentId' )then 
            nBundleid := (select "nBundleid" from "BundleMaster" where "nSectionid" = nSectionid and "cTempid" = rec->>'parentId' limit 1);
            end if;
        else
            nBundleid := nMainbundleid;
        end if;
        nExistsid = (select "nBundleid" from "BundleMaster" where "nSectionid" = nSectionid and "nParentBundleid" IS not distinct from nBundleid and trim(upper("cBundlename")) = trim(upper(rec->>'name')) order by "nBundleid" desc limit 1);
            if (nExistsid IS NULL)then
                parentid := coalesce((select "nBundleid" from "BundleMaster" where "cTempid" = rec->>'parentId' and "nSectionid" = nSectionid order by "nBundleid" desc limit 1), nMainbundleid);
                insert into "BundleMaster"("cBundlename","nParentBundleid","cTempid","nSectionid","nCreateId","dCreateDt")
                values(rec->>'name',parentid,rec->>'id',nSectionid,nUserid,now())
				returning "nBundleid" into nExistsid;
                
                --nExistsid = (select max("nBundleid") from "BundleMaster");
                update temp_folders set "nBundleid" = nExistsid where "id" = rec->>'id';
                update temp_folders set "nParentbundleid" = nExistsid where "parentId" = rec->>'id';
            else
                update "BundleMaster" set "cTempid" = rec->>'id' where "nBundleid" = nExistsid;
                update temp_folders set "nBundleid" = nExistsid where "id" = rec->>'id';
                update temp_folders set "nParentbundleid" = nExistsid where "parentId" = rec->>'id';
            
            end if;

        else

        end if;
        
    END LOOP;

update temp_folders t set "nParentbundleid" = nMainbundleid where trim(coalesce(t."parentId",'0')) = '0';
            
update "UploadDetail" u set "nFiles" = (select count(*) from temp_folders t where "isFolder" = false)
from "JobMaster" j where j."nJobid" = nJobid and j."nUDid" = u."nUDid";

with inserted as (
insert into "BundleDetail"("nBundleid","cFilename","cPath","dCreateDt","nCreateId","nSectionid","cStatus")
select 
    case when coalesce(t."parentId",'0') = '0' then nMainbundleid else coalesce(t."nParentbundleid", null::uuid) end,
    t."name",
    ('doc/case'|| nCaseid || '/dc_'|| floor(random() * 999999999 + 100)::text ||'.'|| split_part(t."name",'.',-1)),
    now(),
    nUserid,
    nSectionid,
    'P'
from temp_folders t
where "isFolder" = false 
and not exists (
    select * from "BundleDetail" bd 
    where bd."nBundleid" = 
        case when coalesce(t."parentId",'0') = '0' then nMainbundleid else coalesce(t."nParentbundleid", null::uuid) end
    and bd."nSectionid" = nSectionid 
    and trim(upper(coalesce(bd."cFilename",''))) = trim(upper(coalesce(t."name",'')))
) 
RETURNING "nBundledetailid"
) 
insert into "BDAttributes"("nBundledetailid")
SELECT "nBundledetailid" FROM inserted;

update temp_folders t set "nBundledetailid" = bd."nBundledetailid","cSavepath" = bd."cPath"
from "BundleDetail" bd 
where bd."nSectionid" = nSectionid 
    and case 
        when trim(coalesce(t."parentId",'0')) = '0' then bd."nBundleid" = nMainbundleid 
        else bd."nBundleid" = t."nParentbundleid" 
        end
    and trim(upper(coalesce(bd."cFilename",''))) = trim(upper(coalesce(t."name",'')));

open ref for 
    select nMainbundleid,"id","name","nBundledetailid","cSavepath","path","parentId","nParentbundleid" 
    from temp_folders 
    where "isFolder" = false;
 
 RETURN ref;
    END;
$function$
